import { execFileSync } from "node:child_process";
import { readFileSync, writeFileSync } from "node:fs";
const git=(...args)=>execFileSync("git",args,{encoding:"utf8"}).trim();
const path="dist/app.js",source=readFileSync(path,"utf8"),m=source.match(/const appVersion = "(\d+)\.(\d+)\.(\d+)";/);
if(!m) throw Error("appVersion missing");
const initial=m.slice(1).map(Number),head=git("rev-parse","HEAD");
const tags=git("tag","--list","mq-prod-v*").split("\n").filter(x=>/^mq-prod-v\d+\.\d+\.\d+$/.test(x));
const number=t=>t.replace("mq-prod-v","").split(".").map(Number);
tags.sort((a,b)=>{const x=number(a),y=number(b);return x[0]-y[0]||x[1]-y[1]||x[2]-y[2]});
const latest=tags.at(-1),baseVersion=latest?number(latest):initial;
if(baseVersion[0]!==initial[0]||baseVersion[1]!==initial[1]) throw Error("release series does not match source");
const previous=latest?git("rev-list","-n","1",latest):"";
let base=previous;if(!base){try{base=git("rev-parse","HEAD^")}catch{base=head}}
const changes=git("diff","--name-only",base,head,"--","dist").split("\n").filter(Boolean);
const newRelease=changes.length>0&&previous!==head;
const version=[baseVersion[0],baseVersion[1],baseVersion[2]+(newRelease?1:0)].join(".");
const tag="mq-prod-v"+version;
if(newRelease&&tags.includes(tag))throw Error("tag already exists for another release");
const build=(process.env.GITHUB_RUN_NUMBER||"local")+"."+(process.env.GITHUB_RUN_ATTEMPT||"1");
const short=head.slice(0,7);
let output=source.replace(m[0],'const appVersion = "'+version+'";');
const label="versionLabel.textContent = "+String.fromCharCode(96)+"Version ${appVersion}"+String.fromCharCode(96)+";";
const replacement="versionLabel.textContent = "+String.fromCharCode(96)+"Version ${appVersion} | Build "+build+" | "+short+String.fromCharCode(96)+";";
if(!output.includes(label))throw Error("version label assignment missing");
output=output.replace(label,replacement);writeFileSync(path,output);
const meta={version,build,commit:head,releaseTag:tag,isNewRelease:newRelease,changedPaths:changes};
writeFileSync("dist/release-meta.json",JSON.stringify(meta,null,2)+"\n");
if(process.env.GITHUB_OUTPUT)writeFileSync(process.env.GITHUB_OUTPUT,`version=${version}\nrelease_tag=${tag}\nis_new_release=${newRelease}\n`,{flag:"a"});
console.log(JSON.stringify(meta));
